arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => activeSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => activeSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => activeSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => activeSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(toastMessage))
{
    <div class="toast @toastType">
        @toastMessage
    </div>
}

@* ===== Profile Section ===== *@
@{
    RenderFragment ProfileSection = __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url">@profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="profileBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ===== Notifications Section ===== *@
@{
    RenderFragment NotificationsSection = __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifEmailEnabled" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifPushEnabled" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifWeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @if (availableChannels != null)
                {
                    @foreach (var channel in availableChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox" checked="@mutedChannels.Contains(ch)"
                                   @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            @ch
                        </label>
                    }
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };
}

@* ===== Security Section ===== *@
@{
    RenderFragment SecuritySection = __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
                </button>
                @if (passwordPanelExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(passwordError))
                        {
                            <p class="error-message">@passwordError</p>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                        @(twoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                    <label class="toggle-label">
                        <input type="checkbox" @bind="twoFactorEnabled" />
                        <span class="toggle-switch"></span>
                    </label>
                </div>
                @if (lastPasswordChange.HasValue)
                {
                    <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (activeSessions != null)
                        {
                            @foreach (var session in activeSessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != activeSessions.FirstOrDefault())
                                        {
                                            <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Confirm Session Revoke</h4>
                        <p>Are you sure you want to revoke this session? The device will be logged out.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeConfirmedSession">Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ===== Appearance Section ===== *@
@{
    RenderFragment AppearanceSection = __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label><input type="radio" name="theme" value="Light" @onchange='() => appearanceTheme = "Light"' checked="@(appearanceTheme == "Light")" /> Light</label>
                    <label><input type="radio" name="theme" value="Dark" @onchange='() => appearanceTheme = "Dark"' checked="@(appearanceTheme == "Dark")" /> Dark</label>
                    <label><input type="radio" name="theme" value="System" @onchange='() => appearanceTheme = "System"' checked="@(appearanceTheme == "System")" /> System</label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label><input type="radio" name="fontSize" value="Small" @onchange='() => appearanceFontSize = "Small"' checked="@(appearanceFontSize == "Small")" /> Small</label>
                    <label><input type="radio" name="fontSize" value="Medium" @onchange='() => appearanceFontSize = "Medium"' checked="@(appearanceFontSize == "Medium")" /> Medium</label>
                    <label><input type="radio" name="fontSize" value="Large" @onchange='() => appearanceFontSize = "Large"' checked="@(appearanceFontSize == "Large")" /> Large</label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="appearanceLanguage">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="appearanceCompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <div class="live-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is a preview of your selected appearance settings.</p>
                <p>The quick brown fox jumps over the lazy dog.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Content looks like this with your current settings.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string activeSection = "Profile";
    private bool loading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";
    private System.Timers.Timer? toastTimer;

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notification state
    private bool notifEmailEnabled;
    private bool notifPushEnabled;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> availableChannels = new();

    // Security state
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession>? activeSessions;
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        savedProfile = profile;
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileAvatarUrl = profile.AvatarUrl;
        profileBio = profile.Bio;

        var notifs = notifTask.Result;
        notifEmailEnabled = notifs.EmailNotifications;
        notifPushEnabled = notifs.PushNotifications;
        notifWeeklyDigest = notifs.WeeklyDigest;
        mutedChannels = new List<string>(notifs.MutedChannels);
        availableChannels = new List<string>(notifs.MutedChannels);

        var security = securityTask.Result;
        twoFactorEnabled = security.TwoFactorEnabled;
        lastPasswordChange = security.LastPasswordChange;
        activeSessions = security.Sessions;

        var appearance = appearanceTask.Result;
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompactMode = appearance.CompactMode;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
    }

    // Notification actions
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!isMuted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        passwordError = "";

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password is required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelExpanded = false;
            lastPasswordChange = DateTime.UtcNow;
            ShowToast("Password updated successfully!", "success");
        }
