@code {
    private string activeSection = "Profile";
    private bool loading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";
    private System.Timers.Timer? toastTimer;

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notification state
    private bool notifEmailEnabled;
    private bool notifPushEnabled;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> availableChannels = new();

    // Security state
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession>? activeSessions;
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        savedProfile = profile;
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileAvatarUrl = profile.AvatarUrl;
        profileBio = profile.Bio;

        var notifs = notifTask.Result;
        notifEmailEnabled = notifs.EmailNotifications;
        notifPushEnabled = notifs.PushNotifications;
        notifWeeklyDigest = notifs.WeeklyDigest;
        mutedChannels = new List<string>(notifs.MutedChannels);
        availableChannels = new List<string>(notifs.MutedChannels);

        var security = securityTask.Result;
        twoFactorEnabled = security.TwoFactorEnabled;
        lastPasswordChange = security.LastPasswordChange;
        activeSessions = security.Sessions;

        var appearance = appearanceTask.Result;
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompactMode = appearance.CompactMode;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
    }

    // Notification actions
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!isMuted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        passwordError = "";

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password is required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelExpanded = false;
            lastPasswordChange = DateTime.UtcNow;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        sessionToRevoke = sessionId;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task RevokeConfirmedSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke);
            activeSessions?.RemoveAll(s => s.Id == sessionToRevoke);
            ShowToast("Session revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    private string GetPreviewStyle()
    {
        var bg = appearanceTheme switch
        {
            "Dark" => "background-color: #1e1e2e; color: #cdd6f4;",
            "Light" => "background-color: #ffffff; color: #1e1e2e;",
            _ => "background-color: #f5f5f5; color: #333;"
        };

        var fontSize = appearanceFontSize switch
        {
            "Small" => "font-size: 12px;",
            "Large" => "font-size: 18px;",
            _ => "font-size: 14px;"
        };

        var padding = appearanceCompactMode ? "padding: 8px;" : "padding: 16px;";

        return $"{bg} {fontSize} {padding} border-radius: 8px; border: 1px solid #ddd;";
    }

    // Toast helper
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        toastTimer?.Dispose();
        toastTimer = new System.Timers.Timer(3000);
        toastTimer.Elapsed += (_, _) =>
        {
            toastMessage = "";
            InvokeAsync(StateHasChanged);
            toastTimer?.Dispose();
        };
        toastTimer.AutoReset = false;
        toastTimer.Start();
    }
}
"}

