+    </div>
+}
+
+@* ===== Profile Section ===== *@
+@{
+    RenderFragment ProfileSection = __builder =>
+    {
+        <section class="settings-section">
+            <h2>Profile</h2>
+
+            <div class="avatar-preview">
+                @if (!string.IsNullOrEmpty(profileAvatarUrl))
+                {
+                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
+                }
+                else
+                {
+                    <div class="avatar-placeholder">No Avatar</div>
+                }
+                <p class="avatar-url">@profileAvatarUrl</p>
+            </div>
+
+            <div class="form-group">
+                <label for="displayName">Display Name</label>
+                <input id="displayName" type="text" @bind="profileDisplayName" />
+            </div>
+
+            <div class="form-group">
+                <label for="email">Email</label>
+                <input id="email" type="email" @bind="profileEmail" />
+            </div>
+
+            <div class="form-group">
+                <label for="bio">Bio</label>
+                <textarea id="bio" rows="4" @bind="profileBio"></textarea>
+            </div>
+
+            <div class="button-group">
+                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
+                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
+            </div>
+        </section>
+    };
+}
+
+@* ===== Notifications Section ===== *@
+@{
+    RenderFragment NotificationsSection = __builder =>
+    {
+        <section class="settings-section">
+            <h2>Notifications</h2>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="notifEmailEnabled" />
+                    <span class="toggle-switch"></span>
+                    Email Notifications
+                </label>
+            </div>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="notifPushEnabled" />
+                    <span class="toggle-switch"></span>
+                    Push Notifications
+                </label>
+            </div>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="notifWeeklyDigest" />
+                    <span class="toggle-switch"></span>
+                    Weekly Digest
+                </label>
+            </div>
+
+            <h3>Muted Channels</h3>
+            <div class="channel-list">
+                @if (availableChannels != null)
+                {
+                    @foreach (var channel in availableChannels)
+                    {
+                        var ch = channel;
+                        <label class="channel-item">
+                            <input type="checkbox" checked="@mutedChannels.Contains(ch)"
+                                   @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
+                            @ch
+                        </label>
+                    }
+                }
+            </div>
+
+            <div class="button-group">
+                <button class="btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
+            </div>
+        </section>
+    };
+}
+
+@* ===== Security Section ===== *@
+@{
+    RenderFragment SecuritySection = __builder =>
+    {
+        <section class="settings-section">
+            <h2>Security</h2>
+
+            <div class="expandable-panel">
+                <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
+                    <span>Change Password</span>
+                    <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
+                </button>
+                @if (passwordPanelExpanded)
+                {
+                    <div class="panel-body">
+                        <div class="form-group">
+                            <label for="currentPassword">Current Password</label>
+                            <input id="currentPassword" type="password" @bind="currentPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="newPassword">New Password</label>
+                            <input id="newPassword" type="password" @bind="newPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="confirmPassword">Confirm Password</label>
+                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
+                        </div>
+                        @if (!string.IsNullOrEmpty(passwordError))
+                        {
+                            <p class="error-message">@passwordError</p>
+                        }
+                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
+                    </div>
+                }
+            </div>
+
+            <div class="two-factor-section">
+                <h3>Two-Factor Authentication</h3>
+                <div class="status-row">
+                    <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
+                        @(twoFactorEnabled ? "● Enabled" : "○ Disabled")
+                    </span>
+                    <label class="toggle-label">
+                        <input type="checkbox" @bind="twoFactorEnabled" />
+                        <span class="toggle-switch"></span>
+                    </label>
+                </div>
+                @if (lastPasswordChange.HasValue)
+                {
+                    <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
+                }
+            </div>
+
+            <div class="sessions-section">
+                <h3>Active Sessions</h3>
+                <table class="sessions-table">
+                    <thead>
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th>Action</th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @if (activeSessions != null)
+                        {
+                            @foreach (var session in activeSessions)
+                            {
+                                <tr>
+                                    <td>@session.Device</td>
+                                    <td>@session.Location</td>
+                                    <td>@session.LastActive.ToString("g")</td>
+                                    <td>
+                                        @if (session != activeSessions.FirstOrDefault())
+                                        {
+                                            <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
+                                                Revoke
+                                            </button>
+                                        }
+                                        else
+                                        {
+                                            <span class="current-badge">Current</span>
+                                        }
+                                    </td>
+                                </tr>
+                            }
+                        }
+                    </tbody>
+                </table>
+            </div>
+
+            @if (showRevokeConfirmation)
+            {
+                <div class="modal-overlay" @onclick="CancelRevoke">
+                    <div class="modal-dialog" @onclick:stopPropagation="true">
+                        <h4>Confirm Session Revoke</h4>
+                        <p>Are you sure you want to revoke this session? The device will be logged out.</p>
+                        <div class="button-group">
+                            <button class="btn-danger" @onclick="RevokeConfirmedSession">Revoke</button>
+                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                        </div>
+                    </div>
+                </div>
+            }
+        </section>
+    };
+}
+
+@* ===== Appearance Section ===== *@
+@{
+    RenderFragment AppearanceSection = __builder =>
+    {
+        <section class="settings-section">
+            <h2>Appearance</h2>
+
+            <div class="form-group">
+                <label>Theme</label>
+                <div class="radio-group">
+                    <label><input type="radio" name="theme" value="Light" @onchange='() => appearanceTheme = "Light"' checked="@(appearanceTheme == "Light")" /> Light</label>
+                    <label><input type="radio" name="theme" value="Dark" @onchange='() => appearanceTheme = "Dark"' checked="@(appearanceTheme == "Dark")" /> Dark</label>
+                    <label><input type="radio" name="theme" value="System" @onchange='() => appearanceTheme = "System"' checked="@(appearanceTheme == "System")" /> System</label>
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label>Font Size</label>
+                <div class="radio-group">
+                    <label><input type="radio" name="fontSize" value="Small" @onchange='() => appearanceFontSize = "Small"' checked="@(appearanceFontSize == "Small")" /> Small</label>
+                    <label><input type="radio" name="fontSize" value="Medium" @onchange='() => appearanceFontSize = "Medium"' checked="@(appearanceFontSize == "Medium")" /> Medium</label>
+                    <label><input type="radio" name="fontSize" value="Large" @onchange='() => appearanceFontSize = "Large"' checked="@(appearanceFontSize == "Large")" /> Large</label>
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label for="language">Language</label>
+                <select id="language" @bind="appearanceLanguage">
+                    <option value="en">English</option>
+                    <option value="es">Spanish</option>
+                    <option value="fr">French</option>
+                    <option value="de">German</option>
+                    <option value="ja">Japanese</option>
+                    <option value="zh">Chinese</option>
+                </select>
+            </div>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="appearanceCompactMode" />
+                    <span class="toggle-switch"></span>
+                    Compact Mode
+                </label>
+            </div>
+
+            <div class="live-preview" style="@GetPreviewStyle()">
+                <h4>Live Preview</h4>
+                <p>This is a preview of your selected appearance settings.</p>
+                <p>The quick brown fox jumps over the lazy dog.</p>
+                <div class="preview-card">
+                    <strong>Sample Card</strong>
+                    <p>Content looks like this with your current settings.</p>
+                </div>
+            </div>
+
+            <div class="button-group">
+                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
+            </div>
+        </section>
+    };
+}
+
+@code {
+    private string activeSection = "Profile";
+    private bool loading = true;
+
+    // Toast
+    private string toastMessage = "";
+    private string toastType = "";
+    private System.Timers.Timer? toastTimer;
+
+    // Profile state
+    private string profileDisplayName = "";
+    private string profileEmail = "";
+    private string profileAvatarUrl = "";
+    private string profileBio = "";
+    private UserProfile? savedProfile;
+
+    // Notification state
+    private bool notifEmailEnabled;
+    private bool notifPushEnabled;
+    private bool notifWeeklyDigest;
+    private List<string> mutedChannels = new();
+    private List<string> availableChannels = new();
+
+    // Security state
+    private bool passwordPanelExpanded;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
+    private string passwordError = "";
+    private bool twoFactorEnabled;
+    private DateTime? lastPasswordChange;
+    private List<ActiveSession>? activeSessions;
+    private bool showRevokeConfirmation;
+    private string? sessionToRevoke;
+
+    // Appearance state
+    private string appearanceTheme = "System";
+    private string appearanceFontSize = "Medium";
+    private string appearanceLanguage = "en";
+    private bool appearanceCompactMode;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllSettings();
+        loading = false;
+    }
+
+    private async Task LoadAllSettings()
+    {
+        var profileTask = SettingsService.GetProfileAsync();
+        var notifTask = SettingsService.GetNotificationPrefsAsync();
+        var securityTask = SettingsService.GetSecuritySettingsAsync();
+        var appearanceTask = SettingsService.GetAppearanceAsync();
+
+        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);
+
+        var profile = profileTask.Result;
+        savedProfile = profile;
+        profileDisplayName = profile.DisplayName;
+        profileEmail = profile.Email;
+        profileAvatarUrl = profile.AvatarUrl;
+        profileBio = profile.Bio;
+
+        var notifs = notifTask.Result;
+        notifEmailEnabled = notifs.EmailNotifications;
+        notifPushEnabled = notifs.PushNotifications;
+        notifWeeklyDigest = notifs.WeeklyDigest;
+        mutedChannels = new List<string>(notifs.MutedChannels);
+        availableChannels = new List<string>(notifs.MutedChannels);
+
+        var security = securityTask.Result;
+        twoFactorEnabled = security.TwoFactorEnabled;
+        lastPasswordChange = security.LastPasswordChange;
+        activeSessions = security.Sessions;
+
+        var appearance = appearanceTask.Result;
+        appearanceTheme = appearance.Theme;
+        appearanceFontSize = appearance.FontSize;
+        appearanceLanguage = appearance.Language;
+        appearanceCompactMode = appearance.CompactMode;
+    }
+
+    // Profile actions
+    private async Task SaveProfile()
+    {
+        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
+        await SettingsService.SaveProfileAsync(profile);
+        savedProfile = profile;
+        ShowToast("Profile saved successfully!", "success");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (savedProfile != null)
+        {
+            profileDisplayName = savedProfile.DisplayName;
+            profileEmail = savedProfile.Email;
+            profileAvatarUrl = savedProfile.AvatarUrl;
+            profileBio = savedProfile.Bio;
+        }
+    }
+
+    // Notification actions
+    private void ToggleMutedChannel(string channel, bool isMuted)
+    {
+        if (isMuted && !mutedChannels.Contains(channel))
+            mutedChannels.Add(channel);
+        else if (!isMuted)
+            mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveNotificationPrefs()
+    {
+        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels);
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security actions
+    private async Task UpdatePassword()
+    {
+        passwordError = "";
+
+        if (string.IsNullOrWhiteSpace(currentPassword))
+        {
+            passwordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(newPassword))
+        {
+            passwordError = "New password is required.";
+            return;
+        }
+        if (newPassword != confirmPassword)
+        {
+            passwordError = "New password and confirmation do not match.";
+            return;
+        }
+
+        try
+        {
+            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+            passwordPanelExpanded = false;
+            lastPasswordChange = DateTime.UtcNow;
+            ShowToast("Password updated successfully!", "success");
+        }
+        catch (Exception ex)
+        {
+            passwordError = ex.Message;
+        }
+    }
+
+    private void ConfirmRevokeSession(string sessionId)
+    {
+        sessionToRevoke = sessionId;
+        showRevokeConfirmation = true;
+    }
+
+    private void CancelRevoke()
+    {
+        showRevokeConfirmation = false;
+        sessionToRevoke = null;
+    }
+
+    private async Task RevokeConfirmedSession()
+    {
+        if (sessionToRevoke != null)
+        {
+            await SettingsService.RevokeSessionAsync(sessionToRevoke);
+            activeSessions?.RemoveAll(s => s.Id == sessionToRevoke);
+            ShowToast("Session revoked.", "success");
+        }
+        showRevokeConfirmation = false;
+        sessionToRevoke = null;
+    }
+
+    // Appearance actions
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        ShowToast("Appearance settings saved!", "success");
+    }
+
+    private string GetPreviewStyle()
+    {
+        var bg = appearanceTheme switch
+        {
+            "Dark" => "background-color: #1e1e2e; color: #cdd6f4;",
+            "Light" => "background-color: #ffffff; color: #1e1e2e;",
+            _ => "background-color: #f5f5f5; color: #333;"
+        };
+
+        var fontSize = appearanceFontSize switch
+        {
+            "Small" => "font-size: 12px;",
+            "Large" => "font-size: 18px;",
+            _ => "font-size: 14px;"
+        };
+
+        var padding = appearanceCompactMode ? "padding: 8px;" : "padding: 16px;";
+
+        return $"{bg} {fontSize} {padding} border-radius: 8px; border: 1px solid #ddd;";
+    }
+
+    // Toast helper
+    private void ShowToast(string message, string type)
+    {
+        toastMessage = message;
+        toastType = type;
+        toastTimer?.Dispose();
+        toastTimer = new System.Timers.Timer(3000);
+        toastTimer.Elapsed += (_, _) =>
+        {
+            toastMessage = "";
+            InvokeAsync(StateHasChanged);
+            toastTimer?.Dispose();
+        };
+        toastTimer.AutoReset = false;
+        toastTimer.Start();
+    }
+}
+

arguments.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    color: #555;
    font-weight: 500;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    color: #1565c0;
    border-left-color: #1565c0;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
    border-bottom: 2px solid #e0e0e0;
    padding-bottom: 0.75rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #444;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #555;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1565c0;
    box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.1);
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f5f5f5;
    border-radius: 8px;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #ddd;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    color: #888;
}

.avatar-url {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
    margin: 0;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.6rem 1.25rem;
    background: #1565c0;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover {
    background: #0d47a1;
}

.btn-secondary {
    padding: 0.6rem 1.25rem;
    background: white;
    color: #555;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background: #f5f5f5;
    border-color: #999;
}

.btn-danger {
    padding: 0.6rem 1.25rem;
    background: #c62828;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #444;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1565c0;
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #f9f9f9;
    border-radius: 6px;
    border: 1px solid #eee;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #333;
    transition: background 0.2s;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #888;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Two-factor */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.status-indicator {
    font-size: 0.9rem;
    font-weight: 500;
}

.status-indicator.enabled {
    color: #2e7d32;
}

.status-indicator.disabled {
    color: #888;
}

.info-text {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

.error-message {
    color: #c62828;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

/* Sessions table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.sessions-table tr:hover {
    background: #f5f5f5;
}

.current-badge {
    font-size: 0.8rem;
    background: #e8f5e9;
    color: #2e7d32;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
