arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => activeSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => activeSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => activeSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => activeSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile</h2>

                <div class="avatar-preview">
                    @if (!string.IsNullOrEmpty(profileAvatarUrl))
                    {
                        <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No Avatar</div>
                    }
                    <p class="avatar-url">@profileAvatarUrl</p>
                </div>

                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="profileDisplayName" />
                </div>

                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="profileEmail" />
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="profileBio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notifications</h2>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifEmailEnabled" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifPushEnabled" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @if (availableChannels != null)
                    {
                        @foreach (var channel in availableChannels)
                        {
                            var ch = channel;
                            <label class="channel-item">
                                <input type="checkbox" checked="@mutedChannels.Contains(ch)"
                                       @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                                @ch
                            </label>
                        }
                    }
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
                </div>
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security</h2>

                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                        <span>Change Password</span>
