@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => activeSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => activeSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => activeSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => activeSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile</h2>

                <div class="avatar-preview">
                    @if (!string.IsNullOrEmpty(profileAvatarUrl))
                    {
                        <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No Avatar</div>
                    }
                    <p class="avatar-url">@profileAvatarUrl</p>
                </div>

                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="profileDisplayName" />
                </div>

                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="profileEmail" />
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="profileBio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notifications</h2>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifEmailEnabled" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifPushEnabled" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @if (availableChannels != null)
                    {
                        @foreach (var channel in availableChannels)
                        {
                            var ch = channel;
                            <label class="channel-item">
                                <input type="checkbox" checked="@mutedChannels.Contains(ch)"
                                       @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                                @ch
                            </label>
                        }
                    }
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
                </div>
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security</h2>

                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                        <span>Change Password</span>
                        <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
                    </button>
                    @if (passwordPanelExpanded)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label for="currentPassword">Current Password</label>
                                <input id="currentPassword" type="password" @bind="currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPassword">New Password</label>
                                <input id="newPassword" type="password" @bind="newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPassword">Confirm Password</label>
                                <input id="confirmPassword" type="password" @bind="confirmPassword" />
                            </div>
                            @if (!string.IsNullOrEmpty(passwordError))
                            {
                                <p class="error-message">@passwordError</p>
                            }
                            <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="two-factor-section">
                    <h3>Two-Factor Authentication</h3>
                    <div class="status-row">
                        <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                            @(twoFactorEnabled ? "● Enabled" : "○ Disabled")
                        </span>
                        <label class="toggle-label">
                            <input type="checkbox" @bind="twoFactorEnabled" />
                            <span class="toggle-switch"></span>
                        </label>
                    </div>
                    @if (lastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>

                <div class="sessions-section">
                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (activeSessions != null)
                            {
                                @foreach (var session in activeSessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != activeSessions.FirstOrDefault())
                                            {
                                                <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>

                @if (showRevokeConfirmation)
                {
                    <div class="modal-overlay" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation="true">
                            <h4>Confirm Session Revoke</h4>
                            <p>Are you sure you want to revoke this session? The device will be logged out.</p>
                            <div class="button-group">
                                <button class="btn-danger" @onclick="RevokeConfirmedSession">Revoke</button>
                                <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance</h2>

                <div class="form-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        <label>
                            <input type="radio" name="theme" value="Light"
                                   checked="@(appearanceTheme == "Light")"
                                   @onchange='() => appearanceTheme = "Light"' /> Light
                        </label>
                        <label>
                            <input type="radio" name="theme" value="Dark"
                                   checked="@(appearanceTheme == "Dark")"
                                   @onchange='() => appearanceTheme = "Dark"' /> Dark
                        </label>
                        <label>
                            <input type="radio" name="theme" value="System"
                                   checked="@(appearanceTheme == "System")"
                                   @onchange='() => appearanceTheme = "System"' /> System
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        <label>
                            <input type="radio" name="fontSize" value="Small"
                                   checked="@(appearanceFontSize == "Small")"
                                   @onchange='() => appearanceFontSize = "Small"' /> Small
                        </label>
                        <label>
                            <input type="radio" name="fontSize" value="Medium"
                                   checked="@(appearanceFontSize == "Medium")"
                                   @onchange='() => appearanceFontSize = "Medium"' /> Medium
                        </label>
                        <label>
                            <input type="radio" name="fontSize" value="Large"
                                   checked="@(appearanceFontSize == "Large")"
                                   @onchange='() => appearanceFontSize = "Large"' /> Large
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label for="language">Language</label>
                    <select id="language" @bind="appearanceLanguage">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="appearanceCompactMode" />
                        <span class="toggle-switch"></span>
                        Compact Mode
                    </label>
                </div>

                <div class="live-preview" style="@GetPreviewStyle()">
                    <h4>Live Preview</h4>
                    <p>This is a preview of your selected appearance settings.</p>
                    <p>The quick brown fox jumps over the lazy dog.</p>
                    <div class="preview-card">
                        <strong>Sample Card</strong>
                        <p>Content looks like this with your current settings.</p>
                    </div>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </section>
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(toastMessage))
{
    <div class="toast @toastType">
        @toastMessage
    </div>
}

